[metadata] {"type": "create", "filePath": "/app/output/styles.css", "content": "/* =========================================================
   LearnForge — Shared Stylesheet
   Colors: #000 (primary), #E6FF32 (lime), #7F2A23 (burgundy)
   ========================================================= */

/* ---- Reset & Base ---- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; font-size: 16px; }
body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  color: #1a1a1a;
  background: #fff;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}
img { max-width: 100%; display: block; }
a { text-decoration: none; color: inherit; }
ul { list-style: none; }
button { cursor: pointer; border: none; background: none; font-family: inherit; }

/* ---- CSS Variables ---- */
:root {
  --black: #000000;
  --lime: #E6FF32;
  --burgundy: #7F2A23;
  --white: #FFFFFF;
  --gray-50: #F9F9F9;
  --gray-100: #F3F3F3;
  --gray-200: #E5E5E5;
  --gray-400: #9E9E9E;
  --gray-600: #5A5A5A;
  --gray-800: #1a1a1a;
  --radius: 12px;
  --radius-lg: 20px;
  --shadow: 0 2px 16px rgba(0,0,0,0.08);
  --shadow-lg: 0 8px 40px rgba(0,0,0,0.12);
  --transition: 0.22s ease;
}

/* ---- Typography ---- */
h1 { font-size: clamp(2.4rem, 5vw, 4rem); font-weight: 900; line-height: 1.08; letter-spacing: -0.03em; }
h2 { font-size: clamp(1.8rem, 3.5vw, 2.8rem); font-weight: 800; line-height: 1.15; letter-spacing: -0.025em; }
h3 { font-size: clamp(1.2rem, 2vw, 1.5rem); font-weight: 700; line-height: 1.3; }
h4 { font-size: 1.1rem; font-weight: 600; }
p { line-height: 1.7; color: var(--gray-600); }

/* ---- Layout ---- */
.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
.section { padding: 96px 0; }
.section-sm { padding: 64px 0; }
.section-dark { background: var(--black); color: var(--white); }
.section-dark p { color: rgba(255,255,255,0.7); }
.section-alt { background: var(--gray-50); }
.section-lime { background: var(--lime); }

.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 32px; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }
.flex { display: flex; }
.flex-center { display: flex; align-items: center; justify-content: center; }
.flex-between { display: flex; align-items: center; justify-content: space-between; }
.gap-16 { gap: 16px; }
.gap-24 { gap: 24px; }
.text-center { text-align: center; }
.mt-8 { margin-top: 8px; }
.mt-16 { margin-top: 16px; }
.mt-24 { margin-top: 24px; }
.mt-32 { margin-top: 32px; }
.mt-48 { margin-top: 48px; }
.mt-64 { margin-top: 64px; }
.mb-8 { margin-bottom: 8px; }
.mb-16 { margin-bottom: 16px; }
.mb-24 { margin-bottom: 24px; }
.mb-32 { margin-bottom: 32px; }
.mb-48 { margin-bottom: 48px; }

/* ---- Buttons ---- */
.btn {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 14px 28px; border-radius: 8px;
  font-size: 0.95rem; font-weight: 600;
  transition: all var(--transition);
  white-space: nowrap;
}
.btn-primary {
  background: var(--black); color: var(--lime);
}
.btn-primary:hover { background: #222; transform: translateY(-1px); box-shadow: 0 4px 16px rgba(0,0,0,0.2); }
.btn-lime {
  background: var(--lime); color: var(--black);
}
.btn-lime:hover { background: #d4ef22; transform: translateY(-1px); box-shadow: 0 4px 16px rgba(230,255,50,0.35); }
.btn-outline {
  background: transparent; color: var(--black);
  border: 2px solid var(--black);
}
.btn-outline:hover { background: var(--black); color: var(--lime); }
.btn-outline-white {
  background: transparent; color: var(--white);
  border: 2px solid rgba(255,255,255,0.4);
}
.btn-outline-white:hover { border-color: var(--lime); color: var(--lime); }
.btn-lg { padding: 18px 36px; font-size: 1.05rem; border-radius: 10px; }
.btn-sm { padding: 10px 20px; font-size: 0.875rem; }

/* ---- Cards ---- */
.card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius);
  padding: 32px;
  transition: all var(--transition);
}
.card:hover { box-shadow: var(--shadow-lg); transform: translateY(-3px); border-color: transparent; }
.card-dark {
  background: #111; border-color: #222;
  color: var(--white);
}
.card-dark p { color: rgba(255,255,255,0.65); }

.card-icon {
  width: 52px; height: 52px;
  background: var(--lime);
  border-radius: 12px;
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 20px;
  font-size: 1.5rem;
}

.section-label {
  display: inline-block;
  font-size: 0.8rem; font-weight: 700; letter-spacing: 0.1em;
  text-transform: uppercase;
  background: var(--lime); color: var(--black);
  padding: 6px 14px; border-radius: 100px;
  margin-bottom: 16px;
}
.section-label-white {
  background: rgba(255,255,255,0.15); color: var(--white);
}

/* ---- Nav ---- */
.nav {
  position: sticky; top: 0; z-index: 100;
  background: var(--black);
  border-bottom: 1px solid #1a1a1a;
  padding: 0;
}
.nav-inner {
  display: flex; align-items: center; justify-content: space-between;
  height: 64px; padding: 0 24px;
  max-width: 1200px; margin: 0 auto;
}
.nav-logo {
  font-size: 1.35rem; font-weight: 900;
  color: var(--white); letter-spacing: -0.04em;
}
.nav-logo span { color: var(--lime); }
.nav-links {
  display: flex; align-items: center; gap: 4px;
}
.nav-links a {
  padding: 8px 14px; border-radius: 6px;
  font-size: 0.9rem; font-weight: 500;
  color: rgba(255,255,255,0.7);
  transition: all var(--transition);
}
.nav-links a:hover, .nav-links a.active { color: var(--white); background: rgba(255,255,255,0.08); }
.nav-cta { display: flex; align-items: center; gap: 12px; }
.nav-hamburger {
  display: none; flex-direction: column; gap: 5px;
  width: 32px; padding: 4px;
}
.nav-hamburger span {
  display: block; height: 2px; background: var(--white);
  border-radius: 2px; transition: all var(--transition);
}
.mobile-nav {
  display: none; background: #111; padding: 16px 24px 24px;
  border-top: 1px solid #1a1a1a;
}
.mobile-nav.open { display: block; }
.mobile-nav a {
  display: block; padding: 12px 0;
  color: rgba(255,255,255,0.8); font-weight: 500;
  border-bottom: 1px solid #1a1a1a;
  transition: color var(--transition);
}
.mobile-nav a:hover { color: var(--lime); }
.mobile-nav .btn { margin-top: 16px; width: 100%; justify-content: center; }

/* ---- Hero ---- */
.hero {
  padding: 100px 0 80px;
  background: var(--white);
  position: relative; overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute; top: -200px; right: -200px;
  width: 600px; height: 600px;
  background: radial-gradient(circle, rgba(230,255,50,0.12) 0%, transparent 70%);
  pointer-events: none;
}
.hero-content { max-width: 760px; }
.hero h1 { margin-bottom: 24px; }
.hero h1 em { font-style: normal; color: var(--burgundy); }
.hero-sub {
  font-size: 1.15rem; color: var(--gray-600);
  max-width: 580px; margin-bottom: 40px;
}
.hero-ctas { display: flex; gap: 14px; flex-wrap: wrap; }

/* Hero Tab Toggle */
.hero-tabs {
  display: flex; gap: 8px; margin-top: 56px; margin-bottom: 20px;
}
.hero-tab {
  padding: 10px 20px; border-radius: 8px;
  font-size: 0.9rem; font-weight: 600;
  border: 2px solid var(--gray-200);
  background: var(--white); color: var(--gray-600);
  cursor: pointer; transition: all var(--transition);
}
.hero-tab.active {
  background: var(--black); color: var(--lime);
  border-color: var(--black);
}
.hero-preview {
  background: var(--gray-50);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 40px;
  min-height: 320px;
  display: none;
}
.hero-preview.active { display: block; }
.preview-header {
  display: flex; align-items: center; gap: 12px;
  margin-bottom: 28px;
}
.preview-dot {
  width: 12px; height: 12px; border-radius: 50%;
}
.preview-dot.red { background: #FF5F57; }
.preview-dot.yellow { background: #FEBC2E; }
.preview-dot.green { background: #28C840; }
.preview-title { font-size: 0.85rem; color: var(--gray-400); margin-left: 8px; }
.preview-grid { display: grid; grid-template-columns: 200px 1fr; gap: 20px; height: 220px; }
.preview-sidebar {
  background: var(--white); border-radius: 10px;
  padding: 16px; border: 1px solid var(--gray-200);
}
.preview-sidebar-item {
  padding: 8px 10px; border-radius: 6px;
  font-size: 0.8rem; font-weight: 500;
  margin-bottom: 4px; cursor: pointer;
  transition: background var(--transition);
}
.preview-sidebar-item.active { background: var(--lime); color: var(--black); }
.preview-sidebar-item:hover { background: var(--gray-100); }
.preview-main {
  background: var(--white); border-radius: 10px;
  padding: 20px; border: 1px solid var(--gray-200);
}
.preview-stat-row { display: flex; gap: 12px; margin-bottom: 16px; }
.preview-stat {
  flex: 1; background: var(--gray-50); border-radius: 8px;
  padding: 12px; text-align: center;
}
.preview-stat .big { font-size: 1.4rem; font-weight: 800; color: var(--black); }
.preview-stat .label { font-size: 0.72rem; color: var(--gray-400); }
.preview-bar { height: 8px; background: var(--gray-200); border-radius: 4px; margin: 8px 0; overflow: hidden; }
.preview-bar-fill { height: 100%; background: var(--lime); border-radius: 4px; }

/* Student preview */
.preview-course-card {
  display: flex; gap: 14px; align-items: flex-start;
  padding: 14px; background: var(--white); border-radius: 10px;
  border: 1px solid var(--gray-200); margin-bottom: 10px;
}
.preview-course-thumb {
  width: 64px; height: 64px; border-radius: 8px;
  background: linear-gradient(135deg, var(--lime) 0%, #a8f000 100%);
  flex-shrink: 0; display: flex; align-items: center; justify-content: center;
  font-size: 1.4rem;
}
.preview-course-info h4 { font-size: 0.85rem; color: var(--black); margin-bottom: 4px; }
.preview-course-info p { font-size: 0.75rem; color: var(--gray-400); margin-bottom: 8px; }
.preview-progress { height: 4px; background: var(--gray-200); border-radius: 2px; }
.preview-progress-fill { height: 100%; background: var(--burgundy); border-radius: 2px; }

/* ---- Stats Bar ---- */
.stats-bar {
  background: var(--black);
  padding: 56px 0;
}
.stats-bar-inner {
  display: flex; justify-content: center; gap: 80px;
  flex-wrap: wrap;
}
.stat-item { text-align: center; }
.stat-number {
  font-size: clamp(2.2rem, 4vw, 3rem);
  font-weight: 900; color: var(--lime);
  letter-spacing: -0.04em; line-height: 1;
  display: block;
}
.stat-label {
  font-size: 0.9rem; color: rgba(255,255,255,0.6);
  margin-top: 8px; font-weight: 500;
}

/* ---- Products Section ---- */
.products-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; }
.product-card {
  background: var(--gray-50);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 32px 28px;
  transition: all var(--transition);
  cursor: pointer;
}
.product-card:hover {
  background: var(--black); color: var(--white);
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}
.product-card:hover p { color: rgba(255,255,255,0.65); }
.product-card:hover .product-icon { background: var(--lime); }
.product-icon {
  width: 52px; height: 52px; border-radius: 12px;
  background: var(--black); display: flex; align-items: center; justify-content: center;
  font-size: 1.5rem; margin-bottom: 20px;
  transition: background var(--transition);
}
.product-card h3 { margin-bottom: 10px; font-size: 1.1rem; }
.product-card p { font-size: 0.9rem; }
.product-card a {
  display: inline-flex; align-items: center; gap: 6px;
  margin-top: 20px; font-size: 0.875rem; font-weight: 600;
  color: var(--black); transition: gap var(--transition);
}
.product-card:hover a { color: var(--lime); }
.product-card a:hover { gap: 10px; }

/* ---- Why Choose Us ---- */
.why-tabs {
  display: flex; gap: 8px; flex-wrap: wrap;
  margin-bottom: 48px; border-bottom: 1px solid var(--gray-200);
  padding-bottom: 0;
}
.why-tab {
  padding: 14px 20px; font-size: 0.9rem; font-weight: 600;
  border-radius: 8px 8px 0 0;
  color: var(--gray-600); border: 2px solid transparent;
  border-bottom: none; background: transparent;
  cursor: pointer; transition: all var(--transition);
  position: relative; bottom: -1px;
}
.why-tab.active {
  color: var(--black); border-color: var(--gray-200);
  border-bottom-color: var(--white); background: var(--white);
}
.why-tab:hover:not(.active) { color: var(--black); background: var(--gray-50); }
.why-panel { display: none; }
.why-panel.active { display: grid; grid-template-columns: 1fr 1fr; gap: 48px; align-items: center; }
.why-features { list-style: none; }
.why-features li {
  display: flex; align-items: flex-start; gap: 14px;
  padding: 14px 0; border-bottom: 1px solid var(--gray-100);
}
.why-features li:last-child { border-bottom: none; }
.why-check {
  width: 24px; height: 24px; border-radius: 50%;
  background: var(--lime); flex-shrink: 0;
  display: flex; align-items: center; justify-content: center;
  font-size: 0.75rem; margin-top: 1px;
}
.why-feature-text { font-size: 0.95rem; font-weight: 500; color: var(--gray-800); }
.why-visual {
  background: var(--gray-50); border-radius: var(--radius-lg);
  padding: 48px; text-align: center; border: 1px solid var(--gray-200);
  min-height: 300px; display: flex; flex-direction: column;
  align-items: center; justify-content: center; gap: 16px;
}
.why-visual-icon { font-size: 4rem; margin-bottom: 8px; }
.why-visual h3 { font-size: 1.3rem; color: var(--black); }
.why-visual p { font-size: 0.9rem; max-width: 280px; text-align: center; }

/* ---- Testimonials ---- */
.testimonials { padding: 96px 0; }
.testimonials-carousel { position: relative; overflow: hidden; }
.testimonials-track {
  display: flex; transition: transform 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}
.testimonial-card {
  min-width: calc(33.333% - 16px); margin-right: 24px;
  background: var(--white); border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg); padding: 36px;
  flex-shrink: 0; transition: box-shadow var(--transition);
}
.testimonial-card:hover { box-shadow: var(--shadow-lg); }
.testimonial-quote {
  font-size: 0.95rem; color: var(--gray-800); line-height: 1.8;
  margin-bottom: 28px; position: relative;
}
.testimonial-quote::before {
  content: '"'; font-size: 4rem; font-weight: 900;
  color: var(--lime); line-height: 1;
  display: block; margin-bottom: -16px;
}
.testimonial-author { display: flex; align-items: center; gap: 14px; }
.testimonial-avatar {
  width: 48px; height: 48px; border-radius: 50%;
  background: linear-gradient(135deg, var(--black), #444);
  display: flex; align-items: center; justify-content: center;
  font-weight: 700; color: var(--lime); font-size: 1.1rem;
}
.testimonial-name { font-weight: 700; font-size: 0.95rem; color: var(--black); }
.testimonial-role { font-size: 0.82rem; color: var(--gray-400); margin-top: 2px; }
.testimonial-tag {
  display: inline-block; margin-bottom: 12px;
  background: var(--lime); color: var(--black);
  font-size: 0.75rem; font-weight: 700;
  padding: 4px 10px; border-radius: 100px; letter-spacing: 0.05em;
}
.carousel-controls {
  display: flex; align-items: center; gap: 12px; margin-top: 36px;
}
.carousel-btn {
  width: 44px; height: 44px; border-radius: 50%;
  background: var(--white); border: 2px solid var(--gray-200);
  display: flex; align-items: center; justify-content: center;
  font-size: 1rem; color: var(--black);
  cursor: pointer; transition: all var(--transition);
}
.carousel-btn:hover { background: var(--black); color: var(--lime); border-color: var(--black); }
.carousel-dots { display: flex; gap: 8px; margin-left: 8px; }
.carousel-dot {
  width: 8px; height: 8px; border-radius: 50%;
  background: var(--gray-200); cursor: pointer;
  transition: all var(--transition);
}
.carousel-dot.active { background: var(--black); width: 24px; border-radius: 4px; }

/* ---- Pricing ---- */
.pricing-intro { max-width: 640px; margin: 0 auto 56px; text-align: center; }
.pricing-badge {
  display: inline-flex; align-items: center; gap: 8px;
  background: var(--gray-50); border: 1px solid var(--gray-200);
  border-radius: 100px; padding: 8px 18px;
  font-size: 0.85rem; font-weight: 600; margin-bottom: 24px;
}
.pricing-badge .dot { width: 8px; height: 8px; border-radius: 50%; background: #22c55e; }
.pricing-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.pricing-card {
  border-radius: var(--radius-lg); padding: 36px;
  border: 2px solid var(--gray-200); background: var(--white);
  transition: all var(--transition);
}
.pricing-card.featured {
  background: var(--black); color: var(--white);
  border-color: var(--black);
}
.pricing-card.featured p { color: rgba(255,255,255,0.65); }
.pricing-card:not(.featured):hover { border-color: var(--black); box-shadow: var(--shadow-lg); }
.pricing-tier { font-size: 0.8rem; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; color: var(--gray-400); margin-bottom: 12px; }
.pricing-card.featured .pricing-tier { color: var(--lime); }
.pricing-price { margin: 20px 0; }
.price-from { font-size: 0.85rem; color: var(--gray-400); }
.price-amount { font-size: 2.6rem; font-weight: 900; color: var(--black); letter-spacing: -0.04em; }
.pricing-card.featured .price-amount { color: var(--lime); }
.price-period { font-size: 0.85rem; color: var(--gray-400); }
.pricing-features { list-style: none; margin: 24px 0; }
.pricing-features li {
  display: flex; gap: 10px; align-items: flex-start;
  padding: 8px 0; font-size: 0.9rem;
  border-bottom: 1px solid rgba(0,0,0,0.05);
}
.pricing-card.featured .pricing-features li { border-color: rgba(255,255,255,0.07); }
.pricing-check { color: #22c55e; font-size: 0.85rem; margin-top: 1px; }
.pricing-enterprise {
  background: var(--gray-50); border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg); padding: 48px;
  text-align: center; margin-top: 32px;
}
.pricing-enterprise h3 { margin-bottom: 12px; }
.pricing-enterprise p { margin-bottom: 28px; max-width: 560px; margin-left: auto; margin-right: auto; }
.enterprise-tags { display: flex; gap: 10px; justify-content: center; flex-wrap: wrap; margin-bottom: 32px; }
.enterprise-tag {
  background: var(--white); border: 1px solid var(--gray-200);
  border-radius: 100px; padding: 8px 16px;
  font-size: 0.85rem; font-weight: 500;
}

/* ---- Integrations ---- */
.integrations-grid {
  display: grid; grid-template-columns: repeat(6, 1fr); gap: 16px;
}
.integration-badge {
  background: var(--white); border: 1px solid var(--gray-200);
  border-radius: 12px; padding: 20px 12px;
  text-align: center; font-size: 0.8rem; font-weight: 600;
  color: var(--gray-800); transition: all var(--transition);
  cursor: default;
}
.integration-badge:hover { border-color: var(--black); box-shadow: var(--shadow); }
.integration-icon { font-size: 1.8rem; margin-bottom: 8px; }

/* ---- FAQ Accordion ---- */
.faq-list { max-width: 800px; margin: 0 auto; }
.faq-item {
  border-bottom: 1px solid var(--gray-200);
}
.faq-question {
  width: 100%; text-align: left;
  display: flex; justify-content: space-between; align-items: center;
  padding: 24px 0; font-size: 1rem; font-weight: 600;
  color: var(--black); cursor: pointer; gap: 16px;
  background: none; border: none;
  transition: color var(--transition);
}
.faq-question:hover { color: var(--burgundy); }
.faq-icon {
  width: 28px; height: 28px; border-radius: 50%;
  background: var(--gray-100); flex-shrink: 0;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.1rem; font-weight: 300; color: var(--black);
  transition: all var(--transition);
}
.faq-item.open .faq-icon { background: var(--black); color: var(--lime); transform: rotate(45deg); }
.faq-answer {
  font-size: 0.95rem; color: var(--gray-600); line-height: 1.75;
  overflow: hidden; max-height: 0;
  transition: max-height 0.35s ease, padding 0.3s ease;
}
.faq-answer-inner { padding-bottom: 24px; }

/* ---- CTA Banner ---- */
.cta-banner {
  background: var(--black); padding: 96px 0; text-align: center;
}
.cta-banner h2 { color: var(--white); margin-bottom: 16px; }
.cta-banner p { color: rgba(255,255,255,0.65); max-width: 560px; margin: 0 auto 40px; font-size: 1.05rem; }
.cta-banner .btn-ctas { display: flex; gap: 14px; justify-content: center; flex-wrap: wrap; }

/* ---- Three Steps ---- */
.steps-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; position: relative; }
.steps-grid::before {
  content: '';
  position: absolute; top: 32px; left: calc(16.67% + 24px); right: calc(16.67% + 24px);
  height: 2px; background: var(--gray-200); z-index: 0;
}
.step-card { position: relative; z-index: 1; }
.step-number {
  width: 64px; height: 64px; border-radius: 50%;
  background: var(--lime); color: var(--black);
  font-size: 1.4rem; font-weight: 900;
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 24px; border: 4px solid var(--white);
  box-shadow: 0 0 0 2px var(--gray-200);
}
.step-card h3 { margin-bottom: 10px; }

/* ---- Tools Grid ---- */
.tools-grid-section { background: var(--gray-50); }
.tools-categories { display: grid; grid-template-columns: repeat(5, 1fr); gap: 24px; }
.tools-category h4 {
  font-size: 0.78rem; font-weight: 700; letter-spacing: 0.08em;
  text-transform: uppercase; color: var(--black);
  border-bottom: 2px solid var(--lime);
  padding-bottom: 8px; margin-bottom: 14px;
}
.tools-list li {
  font-size: 0.875rem; color: var(--gray-600);
  padding: 5px 0;
  display: flex; align-items: center; gap: 8px;
}
.tools-list li::before {
  content: ''; width: 4px; height: 4px; border-radius: 50%;
  background: var(--lime); flex-shrink: 0;
}

/* ---- Value Props ---- */
.value-props { display: grid; grid-template-columns: repeat(3, 1fr); gap: 28px; }
.value-prop {
  padding: 36px; border-radius: var(--radius-lg);
  border: 1px solid var(--gray-200);
  transition: all var(--transition);
}
.value-prop:hover { border-color: var(--black); box-shadow: var(--shadow-lg); }
.value-prop-icon { font-size: 2.4rem; margin-bottom: 20px; }
.value-prop h3 { margin-bottom: 10px; }

/* ---- File Types ---- */
.file-types-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; }
.file-type-badge {
  background: var(--white); border: 1px solid var(--gray-200);
  border-radius: 10px; padding: 20px; text-align: center;
  transition: all var(--transition);
}
.file-type-badge:hover { border-color: var(--black); background: var(--black); color: var(--lime); }
.file-type-icon { font-size: 2rem; margin-bottom: 10px; }
.file-type-name { font-size: 0.875rem; font-weight: 600; }

/* ---- Membership Why ---- */
.membership-why { display: grid; grid-template-columns: repeat(3, 1fr); gap: 28px; }
.membership-why-card { padding: 36px; border-radius: var(--radius-lg); border: 1px solid var(--gray-200); }
.membership-stat { font-size: 2.4rem; font-weight: 900; color: var(--burgundy); margin-bottom: 12px; }

/* ---- Resources ---- */
.resources-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.resource-card {
  border-radius: var(--radius); border: 1px solid var(--gray-200);
  overflow: hidden; transition: all var(--transition);
}
.resource-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-3px); }
.resource-thumb {
  height: 140px; display: flex; align-items: center; justify-content: center;
  font-size: 3rem;
}
.resource-thumb.bg1 { background: linear-gradient(135deg, var(--lime) 0%, #a8f000 100%); }
.resource-thumb.bg2 { background: linear-gradient(135deg, #111 0%, #333 100%); }
.resource-thumb.bg3 { background: linear-gradient(135deg, var(--burgundy) 0%, #a03830 100%); }
.resource-body { padding: 24px; }
.resource-body h4 { margin-bottom: 8px; font-size: 0.95rem; }
.resource-body p { font-size: 0.85rem; margin-bottom: 16px; }
.resource-link { font-size: 0.85rem; font-weight: 600; color: var(--black); display: flex; align-items: center; gap: 6px; }
.resource-link:hover { color: var(--burgundy); }

/* ---- Coaching Spotlight ---- */
.spotlight-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.spotlight-card { padding: 32px; border-radius: var(--radius-lg); border: 1px solid var(--gray-200); }
.spotlight-emoji { font-size: 2.4rem; margin-bottom: 16px; }
.spotlight-card h3 { margin-bottom: 8px; font-size: 1.05rem; }

/* ---- Global Scale ---- */
.global-section { background: var(--black); padding: 96px 0; }
.global-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: center; }
.global-map {
  background: #111; border-radius: var(--radius-lg);
  height: 320px; display: flex; align-items: center; justify-content: center;
  font-size: 6rem; position: relative; overflow: hidden;
}
.global-map::before {
  content: '';
  position: absolute; inset: 0;
  background: radial-gradient(ellipse at center, rgba(230,255,50,0.08) 0%, transparent 70%);
}
.global-points { list-style: none; margin-top: 32px; }
.global-points li {
  display: flex; align-items: center; gap: 12px;
  padding: 12px 0; border-bottom: 1px solid #1a1a1a;
  font-size: 0.95rem; color: rgba(255,255,255,0.8);
}
.global-points li:last-child { border-bottom: none; }
.global-point-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--lime); flex-shrink: 0; }

/* ---- AI Section ---- */
.ai-section { padding: 96px 0; background: var(--gray-50); }
.ai-features { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; margin-top: 56px; }
.ai-feature-card {
  background: var(--white); border: 1px solid var(--gray-200);
  border-radius: var(--radius); padding: 32px;
  transition: all var(--transition);
}
.ai-feature-card:hover { border-color: var(--lime); box-shadow: 0 0 0 2px var(--lime); }
.ai-tag {
  display: inline-block; background: var(--lime); color: var(--black);
  font-size: 0.7rem; font-weight: 700; letter-spacing: 0.1em;
  text-transform: uppercase; padding: 4px 10px; border-radius: 4px;
  margin-bottom: 16px;
}
.ai-feature-card h4 { margin-bottom: 8px; }

/* ---- Product Demo ---- */
.demo-toggle {
  border: 2px solid var(--gray-200); border-radius: var(--radius-lg);
  overflow: hidden; transition: all var(--transition);
}
.demo-toggle.open { border-color: var(--black); }
.demo-toggle-header {
  display: flex; align-items: center; justify-content: space-between;
  padding: 24px 32px; cursor: pointer;
  background: var(--white);
  transition: background var(--transition);
}
.demo-toggle.open .demo-toggle-header { background: var(--black); color: var(--white); }
.demo-toggle-header h3 { font-size: 1.05rem; }
.demo-toggle.open .demo-toggle-header h3 { color: var(--white); }
.demo-arrow {
  width: 32px; height: 32px; border-radius: 50%;
  background: var(--gray-100); display: flex; align-items: center; justify-content: center;
  font-size: 0.8rem; transition: all var(--transition);
}
.demo-toggle.open .demo-arrow { background: var(--lime); transform: rotate(180deg); }
.demo-body {
  max-height: 0; overflow: hidden;
  transition: max-height 0.4s ease;
}
.demo-body-inner {
  padding: 40px 32px;
  background: var(--gray-50);
  border-top: 1px solid var(--gray-200);
}
.demo-features { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.demo-feature h4 { margin-bottom: 8px; font-size: 0.95rem; }
.demo-feature p { font-size: 0.85rem; }

/* ---- Footer ---- */
footer {
  background: var(--black); color: rgba(255,255,255,0.6);
  padding: 64px 0 32px;
}
.footer-grid { display: grid; grid-template-columns: 2fr 1fr 1fr 1fr 1fr; gap: 48px; margin-bottom: 56px; }
.footer-brand .nav-logo { display: block; margin-bottom: 16px; font-size: 1.5rem; }
.footer-brand p { font-size: 0.875rem; line-height: 1.7; max-width: 280px; }
.footer-col h5 {
  font-size: 0.8rem; font-weight: 700; letter-spacing: 0.08em;
  text-transform: uppercase; color: var(--white);
  margin-bottom: 18px;
}
.footer-col ul li { margin-bottom: 10px; }
.footer-col ul li a {
  font-size: 0.875rem; transition: color var(--transition);
}
.footer-col ul li a:hover { color: var(--lime); }
.footer-bottom {
  border-top: 1px solid #1a1a1a; padding-top: 28px;
  display: flex; justify-content: space-between; align-items: center;
  flex-wrap: wrap; gap: 16px;
}
.footer-bottom p { font-size: 0.825rem; }
.footer-legal { display: flex; gap: 24px; }
.footer-legal a { font-size: 0.825rem; transition: color var(--transition); }
.footer-legal a:hover { color: var(--lime); }

/* ---- Social Proof ---- */
.social-proof { background: var(--lime); padding: 56px 0; }
.social-proof-inner { text-align: center; }
.social-proof h2 { color: var(--black); margin-bottom: 10px; }
.social-proof p { color: rgba(0,0,0,0.65); margin-bottom: 32px; }
.trust-badges { display: flex; justify-content: center; gap: 32px; flex-wrap: wrap; }
.trust-badge { display: flex; align-items: center; gap: 10px; font-size: 0.9rem; font-weight: 600; color: var(--black); }
.trust-badge-icon { font-size: 1.4rem; }

/* ---- Page Hero Variants ---- */
.hero-product { background: var(--black); padding: 100px 0 80px; }
.hero-product h1 { color: var(--white); }
.hero-product h1 em { font-style: normal; color: var(--lime); }
.hero-product .hero-sub { color: rgba(255,255,255,0.7); }

/* ---- Scroll animation ---- */
.fade-up {
  opacity: 0; transform: translateY(24px);
  transition: opacity 0.55s ease, transform 0.55s ease;
}
.fade-up.visible { opacity: 1; transform: none; }

/* ---- Responsive ---- */
@media (max-width: 1024px) {
  .products-grid { grid-template-columns: repeat(2, 1fr); }
  .integrations-grid { grid-template-columns: repeat(4, 1fr); }
  .tools-categories { grid-template-columns: repeat(3, 1fr); }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
  .footer-brand { grid-column: 1 / -1; }
}
@media (max-width: 768px) {
  .section { padding: 64px 0; }
  .grid-2, .grid-3, .grid-4 { grid-template-columns: 1fr; }
  .products-grid { grid-template-columns: 1fr; }
  .steps-grid { grid-template-columns: 1fr; }
  .steps-grid::before { display: none; }
  .pricing-grid { grid-template-columns: 1fr; }
  .tools-categories { grid-template-columns: repeat(2, 1fr); }
  .integrations-grid { grid-template-columns: repeat(3, 1fr); }
  .file-types-grid { grid-template-columns: repeat(2, 1fr); }
  .membership-why { grid-template-columns: 1fr; }
  .resources-grid { grid-template-columns: 1fr; }
  .spotlight-grid { grid-template-columns: 1fr; }
  .value-props { grid-template-columns: 1fr; }
  .ai-features { grid-template-columns: 1fr; }
  .demo-features { grid-template-columns: 1fr; }
  .global-grid { grid-template-columns: 1fr; }
  .stats-bar-inner { gap: 40px; }
  .why-panel.active { grid-template-columns: 1fr; }
  .nav-links, .nav-cta .btn-outline-nav { display: none; }
  .nav-hamburger { display: flex; }
  .testimonial-card { min-width: calc(90% - 16px); }
  .footer-grid { grid-template-columns: 1fr; }
  .hero-tabs { flex-wrap: wrap; }
  .preview-grid { grid-template-columns: 1fr; height: auto; }
  .preview-sidebar { display: none; }
  .why-tabs { overflow-x: auto; flex-wrap: nowrap; padding-bottom: 1px; }
  .why-tab { white-space: nowrap; }
}
@media (max-width: 480px) {
  h1 { font-size: 2rem; }
  h2 { font-size: 1.6rem; }
  .integrations-grid { grid-template-columns: repeat(2, 1fr); }
  .tools-categories { grid-template-columns: 1fr; }
  .hero-ctas { flex-direction: column; }
  .cta-banner .btn-ctas { flex-direction: column; align-items: center; }
  .trust-badges { flex-direction: column; align-items: center; }
  .footer-bottom { flex-direction: column; text-align: center; }
  .footer-legal { flex-wrap: wrap; justify-content: center; }
}
